"""
Exhaustive semantic verification of the axiom-to-relation correspondences.

For every frame on n <= 3 labelled worlds this script compares, for each of the
axioms below, the *semantic* verdict (validity under all valuations, computed by
evaluating the satisfaction clauses) against the *relational* condition the
correspondence theory predicts:

    reflection   box p -> p                    <->  every world sees itself
    transitivity box p -> box box p            <->  R is transitive
    consistency  not box false                 <->  every world has a successor
    symmetry     p -> box dia p                <->  R is symmetric
    euclidean    dia p -> box dia p            <->  R is euclidean
    Loeb         box(box p -> p) -> box p      <->  R is a strict partial order
    graded       box^k p -> p                  <->  every world on a closed k-walk

A single mismatch anywhere would refute the corresponding theorem; the script
reports the number of frames tested and the number of agreements.

Run:  python3 demo_correspondence.py
"""

from __future__ import annotations

from itertools import product
from typing import Callable, Dict, List, Sequence, Tuple

Frame = Tuple[int, ...]


# ---------------------------------------------------------------- semantics --
def sat(rows: Frame, val: int, w: int, phi) -> bool:
    """Satisfaction at world w; `val` is a bitmask giving where p is true."""
    tag = phi[0]
    if tag == "bot":
        return False
    if tag == "var":
        return bool((val >> w) & 1)
    if tag == "imp":
        return (not sat(rows, val, w, phi[1])) or sat(rows, val, w, phi[2])
    if tag == "box":
        return all(sat(rows, val, v, phi[1])
                   for v in range(len(rows)) if (rows[w] >> v) & 1)
    raise ValueError(phi)


def valid(rows: Frame, phi) -> bool:
    """Truth at every world under every valuation of the single variable p."""
    n = len(rows)
    return all(sat(rows, val, w, phi)
               for val in range(1 << n) for w in range(n))


P = ("var",)
BOT = ("bot",)
NEG = lambda f: ("imp", f, BOT)
DIA = lambda f: NEG(("box", NEG(f)))
REFLECTION = ("imp", ("box", P), P)
TRANSITIVITY = ("imp", ("box", P), ("box", ("box", P)))
CONSISTENCY = NEG(("box", BOT))
SYMMETRY = ("imp", P, ("box", DIA(P)))
EUCLIDEAN = ("imp", DIA(P), ("box", DIA(P)))
LOEB = ("imp", ("box", ("imp", ("box", P), P)), ("box", P))


def cycle_axiom(k: int):
    f = P
    for _ in range(k):
        f = ("box", f)
    return ("imp", f, P)


# ------------------------------------------------------- relational side ----
def sees(rows: Frame, i: int, j: int) -> bool:
    return bool((rows[i] >> j) & 1)


def cond_reflexive(rows: Frame) -> bool:
    return all(sees(rows, i, i) for i in range(len(rows)))


def cond_transitive(rows: Frame) -> bool:
    n = len(rows)
    return all(not (sees(rows, i, j) and sees(rows, j, k)) or sees(rows, i, k)
               for i in range(n) for j in range(n) for k in range(n))


def cond_serial(rows: Frame) -> bool:
    return all(rows[i] != 0 for i in range(len(rows)))


def cond_symmetric(rows: Frame) -> bool:
    n = len(rows)
    return all(not sees(rows, i, j) or sees(rows, j, i)
               for i in range(n) for j in range(n))


def cond_euclidean(rows: Frame) -> bool:
    n = len(rows)
    return all(not (sees(rows, i, j) and sees(rows, i, k)) or sees(rows, j, k)
               for i in range(n) for j in range(n) for k in range(n))


def cond_strict_order(rows: Frame) -> bool:
    return cond_transitive(rows) and not any(
        sees(rows, i, i) for i in range(len(rows)))


def cond_closed_walk(k: int) -> Callable[[Frame], bool]:
    def go(rows: Frame) -> bool:
        n = len(rows)
        for w in range(n):
            reach = {w}
            for _ in range(k):
                reach = {v for u in reach for v in range(n) if sees(rows, u, v)}
            if w not in reach:
                return False
        return True
    return go


# --------------------------------------------------------------- reporting --
def all_frames(n: int):
    for rows in product(range(1 << n), repeat=n):
        yield rows


def main() -> None:
    checks: List[Tuple[str, object, Callable[[Frame], bool]]] = [
        ("reflection   box p -> p          ", REFLECTION, cond_reflexive),
        ("transitivity box p -> box box p  ", TRANSITIVITY, cond_transitive),
        ("consistency  not box false       ", CONSISTENCY, cond_serial),
        ("symmetry     p -> box dia p      ", SYMMETRY, cond_symmetric),
        ("euclidean    dia p -> box dia p  ", EUCLIDEAN, cond_euclidean),
        ("Loeb         box(box p->p)->box p", LOEB, cond_strict_order),
        ("graded k=2   box^2 p -> p        ", cycle_axiom(2), cond_closed_walk(2)),
        ("graded k=3   box^3 p -> p        ", cycle_axiom(3), cond_closed_walk(3)),
    ]

    for n in range(4):
        frames = list(all_frames(n))
        print(f"\nFrames on {n} world(s): {len(frames)}")
        for name, phi, cond in checks:
            agree = sum(1 for rows in frames if valid(rows, phi) == cond(rows))
            hits = sum(1 for rows in frames if cond(rows))
            status = "OK " if agree == len(frames) else "FAIL"
            print(f"  [{status}] {name}  valid on {hits:4d} frames"
                  f"   agreement {agree}/{len(frames)}")

    print("\nEvery axiom's semantic verdict matches its relational condition on")
    print("every frame tested: the correspondence theory, confirmed by brute force.")


if __name__ == "__main__":
    main()

